CREATE TRIGGER trg_rez_durum_guncelle
AFTER UPDATE ON rezervasyonlar
FOR EACH ROW
BEGIN
  IF OLD.durum <> NEW.durum THEN
    UPDATE odalar SET durum = IF(NEW.durum='IPTAL','MUSAIT','DOLU')
      WHERE id = NEW.oda_id;
    INSERT INTO rezervasyon_log(rez_id, eski, yeni, zaman)
      VALUES (NEW.id, OLD.durum, NEW.durum, NOW());
  END IF;
END;

-- Önce: İndekssiz Full Table Scan (yüzlerce ms)
SELECT * FROM rezervasyonlar WHERE oda_id = 204;
-- Sonra: Doğru kolonlara bileşik B-Tree indeksi
CREATE INDEX idx_rez_oda_tarih
  ON rezervasyonlar (oda_id, giris_tarihi, cikis_tarihi);
SELECT EXISTS(SELECT 1 FROM rezervasyonlar WHERE oda_id = 204);
